window.NAGA=[{"key": "n_xWIAWmMZioo", "id": "xWIAWmMZioo", "who": "Dr Osama Naga", "title": "Pediatric GI, Part 1: Nutrition and acute abdomen", "len": 3656, "approx": false, "sys": "gi", "sections": [{"t": 0, "title": "Calories and infant formula", "notes": ["Carbohydrate and protein **4 kcal/g**, fat **9 kcal/g**.", "Formula: **20 kcal per 30 mL (1 oz)**. Term and preterm need **100 to 140 kcal/kg/day**, malnourished kids 20 to 30% more for catch-up.", "Protein: preterm **3.5 g/kg/day**, term 2 to 2.5 g/kg/day."]}, {"t": 98, "title": "Breast milk and breastfeeding contraindications", "notes": ["Breast milk: carbohydrate **lactose**, protein alpha-lactalbumin, fat ARA and DHA.", "Absolute contraindications: **HIV** (even on treatment), **HTLV**, **active untreated TB** (fine after 2 weeks of treatment), infant **classic galactosemia**.", "Fine to breastfeed: **hepatitis B or C**, maternal fever, mastitis or breast abscess, smoking (counsel to quit), infant jaundice (feed more often)."]}, {"t": 194, "title": "Preterm formula", "notes": ["Carbohydrate: corn syrup solids (glucose polymers). Whey to casein 60:40, like human milk. Fat: **medium-chain triglycerides**.", "**Calcium to phosphorus 2:1** for best calcium absorption (matters for preterm TPN). Zinc high, over 10 times copper."]}, {"t": 231, "title": "Marasmus vs kwashiorkor", "notes": ["**Marasmus**: non-edematous, severe energy and protein lack. Severe wasting, hypotonia, wrinkled old-man face, listless, low temperature, slow pulse.", "**Kwashiorkor**: edematous, **protein lack with adequate carbohydrate**. Low albumin causes **edema** and puffy face. Low lipoprotein synthesis causes **fatty liver**, so the big belly is liver.", "Kwashiorkor: infections (no antibodies), apathy, irritability, **flaky mosaic skin** (low zinc, looks like acrodermatitis enteropathica), sparse **red or grey streaky hair**."]}, {"t": 386, "title": "Thiamine (B1) and riboflavin (B2)", "notes": ["B1 deficiency causes: TPN without thiamine, **chronic alcohol use**. Infantile beriberi: **heart failure**, hoarseness or aphonia, absent reflexes. Adults: **Wernicke** (confusion, ataxia, ophthalmoplegia, nystagmus). Give IV thiamine to alcohol users in the ED.", "B2 deficiency: **prolonged phototherapy** (destroys riboflavin), adolescent girls, low income. Signs: **angular stomatitis and cheilitis, glossitis**, keratitis, photophobia, **seborrheic dermatitis**, anemia."]}, {"t": 487, "title": "Niacin (B3) and pyridoxine (B6)", "notes": ["B3: alcohol, **prolonged isoniazid**, malabsorption, anorexia. **3 Ds: diarrhea, dermatitis, dementia**.", "B6: **isoniazid** (supplement B6 on TB treatment), breastfed over 6 months by a deficient mother.", "**Pyridoxine-dependent seizures**: intractable seizures under 18 months, can start in utero. Any persistent seizure with no clear cause gets a **trial of pyridoxine**. B6 deficiency also gives microcytic anemia, neuropathy, dermatitis."]}, {"t": 593, "title": "B12 deficiency", "notes": ["Case: 1-year-old, **strict vegan mother**, pale, macrocytic anemia.", "B12 comes **only from animal foods**. Causes: vegan diet, **ileal resection or Crohn of the ileum**, pernicious anemia, exclusive breastfeeding by a deficient mother.", "Picture: **megaloblastic anemia, hypersegmented neutrophils**, paresthesias, **posterior column loss (vibration)**, hyperpigmentation, failure to thrive. Low maternal B12 in pregnancy: neural tube defects. Treat the cause, then B12."]}, {"t": 779, "title": "Folate deficiency", "notes": ["Case: 6-month-old on **homemade goat's milk formula**, macrocytic anemia. **Goat's milk lacks folate**.", "Causes: goat's milk, Crohn, sickle cell, malignancy, **phenytoin, methotrexate**, MTHFR deficiency.", "Macrocytic anemia: check **serum folate and B12**. Never treat B12 deficiency with folate alone, neuro signs get worse."]}, {"t": 890, "title": "Vitamin C deficiency (scurvy)", "notes": ["Case: 7-month-old on **evaporated boiled milk**, **bleeding gums**, won't move legs, **frog-leg position**.", "Signs: gingivitis and bleeding gums, perifollicular hemorrhage, **leg pain from subperiosteal hemorrhage**, hemarthrosis, pseudoparalysis, poor wound healing.", "Too much vitamin C: **kidney stones**, diarrhea, hemolysis in G6PD."]}, {"t": 1018, "title": "Fat-soluble vitamins and vitamin A", "notes": ["**A, D, E, K** need bowel surface and enzymes: low in **short bowel, cystic fibrosis, celiac, cholestasis**.", "Vitamin A deficiency: first sign **night blindness**, then xerophthalmia, **Bitot spots**, corneal ulcer, **keratomalacia** (emergency, IV vitamin A). Follicular hyperkeratosis.", "**Measles: give vitamin A** (deficiency raises mortality).", "Too much vitamin A: **idiopathic intracranial hypertension** (headache, papilledema, normal CT, high opening pressure), hepatosplenomegaly, alopecia."]}, {"t": 1240, "title": "Vitamin D deficiency", "notes": ["Case: 16-month-old, **exclusively breastfed with no supplement**, no teeth, **rachitic rosary**, wide wrists, bowed legs.", "All breastfed babies need **vitamin D from birth**. Signs: poor growth, tetany from low calcium, weakness, bone deformities, **delayed teeth**.", "Too much vitamin D: **hypercalcemia**, constipation, nephrocalcinosis, kidney stones."]}, {"t": 1340, "title": "Vitamin E deficiency", "notes": ["Case: ex-24-weeker with **cholestatic jaundice** awaiting transplant, **hyporeflexia**, weakness, low alpha-tocopherol.", "Causes: **biliary atresia**, very low birth weight preterms, **cystic fibrosis**, malabsorption.", "Signs: **areflexia, ataxia, loss of position and vibration sense**, ophthalmoplegia, **hemolytic anemia in preterms**."]}, {"t": 1440, "title": "Vitamin K deficiency bleeding", "notes": ["Case: 5-day-old **born at home**, bleeding from the umbilical stump: **no vitamin K at birth**.", "Vitamin K makes **factors 2, 7, 9, 10**. Breast milk is low in it, it doesn't cross the placenta, and the newborn gut has no flora yet.", "Diagnosis: **prolonged PT**. Prevention: **0.5 to 1 mg IM at birth**. Treat with vitamin K, then fresh frozen plasma."]}, {"t": 1566, "title": "Iron deficiency anemia", "notes": ["Peak at 6 to 20 months, especially exclusively breastfed. Iron supplement from **4 months for term, from birth for preterm** (US guidance).", "Picture: poor school work, irritability, glossitis, angular cheilitis, **pica and pagophagia (ice)**, more lead absorption, **lower IQ**."]}, {"t": 1627, "title": "Zinc, copper, selenium, biotin, iodine", "notes": ["Zinc: alopecia, diarrhea, dermatitis, infections, poor growth, loss of taste. **Acrodermatitis enteropathica**: autosomal recessive, starts **after weaning**, scaly rash around the **mouth and anus**, alopecia, diarrhea.", "Copper: microcytic anemia, **neutropenia**, metaphyseal flaring like rickets with normal vitamin D. **Menkes**: X-linked, **kinky colourless hair**, seizures, hypotonia, low copper and ceruloplasmin.", "Selenium: **cardiomyopathy**. Biotin: alopecia, dermatitis, hypotonia. Iodine: goitre, **cretinism**."]}, {"t": 1775, "title": "Carotenemia and refeeding syndrome", "notes": ["**Carotenemia**: yellow skin (nose), **white sclera**, lots of carrots. Reassure.", "**Refeeding syndrome**: full calories too fast in severe malnutrition (anorexia). Insulin drives **phosphate, magnesium and potassium** into cells: **severe hypophosphatemia**, ATP depletion, organ failure, death."]}, {"t": 1847, "title": "Failure to thrive", "notes": ["Weight under the 3rd to 5th percentile for length, **dropping 2 major percentile lines**, or under 80% of ideal weight. Plot weight, length and head circumference.", "Causes to think of: reflux, **malrotation with intermittent volvulus**, raised intracranial pressure, **celiac (after 6 months)**, abuse, cow's milk protein allergy, heart failure, **renal tubular acidosis, UTI**, hyperthyroidism, Russell-Silver.", "**Weight falls before height**: GI or nutritional cause (cystic fibrosis, celiac)."]}, {"t": 2000, "title": "Failure to thrive workup and management", "notes": ["Labs: CBC, chemistry (acidosis, RTA, kidney and liver), **anti-tTG IgA (with IgA level)**, stool fat and reducing substances, **sweat chloride even without lung symptoms**, TSH and T4, urinalysis.", "Admit if: severe malnutrition, unstable, outpatient care failing, **abuse or neglect**, poor parent-child interaction.", "Management: **multidisciplinary**, watch a feed, more and better calories, OT and speech for food aversion, treat the cause."]}, {"t": 2119, "title": "Acute abdominal pain: causes", "notes": ["Sudden pain with **bilious vomiting and distension: midgut volvulus**. Colicky pain and lethargy at about 9 months: intussusception.", "Always think of **ovarian torsion** in girls and **testicular torsion** in boys (hours to save it).", "Trauma: spleen or liver rupture, **duodenal hematoma (bike handlebar)**, abuse. Right lower lobe pneumonia can present as abdominal pain.", "Teen girls: **pregnancy test**, PID, Fitz-Hugh-Curtis, ectopic. Also constipation, gastroenteritis, mesenteric adenitis, UTI."]}, {"t": 2296, "title": "Appendicitis: diagnosis", "notes": ["Missed most often in **young children**, who perforate most. Anorexia and fever can be absent.", "Pain worse with **walking or movement**, progressive. **Localized tenderness is the single most reliable finding**, repeat the exam. Use gentle percussion, not deep palpation.", "Look-alikes: **mesenteric adenitis** (gets better, enlarged nodes, normal appendix, Yersinia from raw pork), **right lower lobe pneumonia** (chest x-ray)."]}, {"t": 2433, "title": "Appendicitis: signs, labs and imaging", "notes": ["Rovsing (left lower quadrant pressure hurts right), obturator (internal rotation of flexed hip), psoas (hip extension). Dunphy (cough), Markle (heel drop).", "CBC can be normal in the first 24 hours. WBC over 20,000 suggests perforation. Urine can have WBCs but **no bacteria**.", "**Ultrasound first**: wall over **6 mm**, non-compressible. Must see a normal appendix to rule it out. CT is the gold standard but avoid if possible."]}, {"t": 2602, "title": "Appendicitis: management", "notes": ["Classic case on the exam: **straight to surgery**, no more tests.", "**Morphine does not reduce diagnostic accuracy**, treat the pain.", "Antibiotics: one preop dose. Perforated: 3 to 5 days (ampicillin, gentamicin plus clindamycin or metronidazole, or ceftriaxone plus metronidazole)."]}, {"t": 2675, "title": "Midgut volvulus", "notes": ["**Surgical emergency** with persistent bilious vomiting. Malrotation lets bowel twist and cut off its blood supply: necrosis, short bowel, death.", "Usually **under 1 year**, can be any age. Bilious vomiting can be absent if the twist is above the ampulla.", "Older kids: pain. Infants: lethargy, poor feeding, crying. **Rectal bleeding is late** (ischemia).", "Upper GI contrast is the main test: **corkscrew** duodenum or abrupt cutoff. Plain film: dilated stomach and proximal duodenum. Call surgery **before any test**."]}, {"t": 2810, "title": "Intussusception", "notes": ["**Most common cause of intestinal obstruction** in infants. Usually ileocolic.", "Lead points explain older kids: **Meckel**, polyps, **lymphoma**, duplication cyst, HSP. Infants: idiopathic, enlarged nodes after a virus.", "Intermittent colicky pain (constant pain points to appendicitis), **lethargy out of proportion**, may be the only sign. Vomiting can be absent or bilious.", "**Currant jelly stool is late**, a non-bloody stool doesn't rule it out. Sausage mass in the **right upper quadrant**, empty right lower quadrant."]}, {"t": 2965, "title": "Intussusception: imaging and recurrence", "notes": ["Ultrasound: **target or donut sign**, very sensitive and specific.", "**Air contrast enema is diagnostic and therapeutic**. On the board, pick air enema over ultrasound for a classic case.", "Recurrence about **10%**, most within **72 hours**. Repeat the enema. More than one recurrence suggests a **lead point**."]}, {"t": 3076, "title": "Ileus", "notes": ["Poor motility without obstruction: pain, distension, vomiting, **hypoactive bowel sounds**.", "Causes: surgery, infection and sepsis, **hypokalemia**, narcotics, anesthetics, chemo.", "Supportive: stop feeds, IV fluids, NG tube only if vomiting or distended, treat the cause."]}, {"t": 3136, "title": "Acute pancreatitis", "notes": ["Most common cause in kids: **blunt abdominal trauma** (handlebar, abuse). Also biliary anomalies, drugs (**valproate, L-asparaginase, steroids, tetracycline, azathioprine**), viruses, **high triglycerides, hypercalcemia**, cystic fibrosis. 25% unknown.", "Pain often does **not radiate to the back** in kids. Pseudocyst: epigastric mass.", "**Amylase and lipase 3 times normal**, lipase more specific. Normal levels don't rule it out. First imaging: **ultrasound**. CT if tumour suspected.", "Treatment: NPO (can eat if no pain), IV fluids, analgesia (narcotics for severe pain), acid suppression, NG if vomiting. Pseudocyst under 5 cm: watch 4 to 6 weeks."]}, {"t": 3300, "title": "Recurrent pancreatitis", "notes": ["Causes: **hypertriglyceridemia**, hypercalcemia, **hereditary pancreatitis** (most common cause of relapsing pancreatitis in the US).", "Risks: pancreatic insufficiency, adenocarcinoma, pseudocyst.", "Case: recurrent pain, family history of **early cardiac death**, high lipase: **hyperlipidemia**."]}, {"t": 3400, "title": "Acute cholecystitis and gallstones", "notes": ["Causes: **gallstones**, hemolysis (**sickle cell, G6PD**), TPN, **ceftriaxone**, ileal resection, cystic fibrosis. Acalculous: critical illness and sepsis.", "Right upper quadrant pain, **Murphy sign**, fever, vomiting, jaundice.", "Cholesterol stones are radiolucent. **Pigment stones are black, radiopaque, from hemolysis**. Ultrasound first, HIDA if not seen.", "Treatment: NPO, IV fluids, pain control, antibiotics if febrile or sick, cholecystectomy timing with surgery."]}, {"t": 3500, "title": "Choledocholithiasis and cholangitis", "notes": ["Stone in the common bile duct: obstructive jaundice, high direct bilirubin, GGT and alkaline phosphatase.", "Cholangitis: infection behind the stone (fever, jaundice, right upper quadrant pain). Needs antibiotics and duct drainage."]}], "tx": true}, {"key": "n_ovVm2EeacU4", "id": "ovVm2EeacU4", "who": "Dr Osama Naga", "title": "Pediatric GI, Part 2: Upper and lower GI", "len": 4764, "approx": true, "sys": "gi", "sections": [{"t": 0, "title": "Esophageal atresia and rumination", "notes": ["Esophageal atresia: choking with feeds, **NG tube will not pass**.", "Rumination: effortless regurgitation of recent food, often with psychosocial stress. **Multidisciplinary and behavioural therapy**."]}, {"t": 270, "title": "Reflux (GER vs GERD)", "notes": ["Happy spitter: peaks around 4 months, **gone by 12 to 24 months**, reassure.", "Trial **thickened feeds or a 2-week hydrolyzed formula** (or maternal dairy elimination if breastfed) to test for cow's milk protein allergy.", "Severe GERD failing treatment: GI referral, **fundoplication** last resort."]}, {"t": 635, "title": "Eosinophilic esophagitis", "notes": ["Eosinophils infiltrate the esophagus, driven by **food allergy**.", "Vomiting, chest or epigastric pain, dysphagia, **food impaction** in a teen. Suspect when acid suppression fails.", "Diagnosis: **endoscopy with biopsy**. Treat with diet elimination, PPI or swallowed steroids, repeat scopes."]}, {"t": 780, "title": "Pill esophagitis", "notes": ["History is key: pill (doxycycline, NSAIDs, iron) taken with little water before lying down.", "Treat by stopping the pill, drink a full glass of water upright."]}, {"t": 880, "title": "Foreign body ingestion", "notes": ["Most common at **6 months to 3 years**. Get x-rays, but food, wood, plastic and aluminum can be invisible.", "Coin vs **button battery**: battery has a halo (double ring).", "**Battery in the esophagus: remove immediately**. Symptomatic: remove. Blunt asymptomatic coin in the esophagus: can wait up to 24 hours."]}, {"t": 1140, "title": "Caustic ingestion", "notes": ["**Alkali** may show no mouth burns but deep esophageal injury. Acids injure the stomach. A clean mouth does not rule out injury.", "Drooling, dysphagia, abdominal pain, stridor.", "**Do not neutralize or induce vomiting**. Endoscopy 12 to 24 hours after (not after about 5 days). Late complication: **strictures**."]}, {"t": 1240, "title": "Vomiting differential: UTI and appendicitis", "notes": ["Always **test the urine** in a vomiting child.", "Appendicitis in young children can present with vomiting with or without pain or fever."]}, {"t": 1320, "title": "Cyclic vomiting syndrome", "notes": ["Stereotyped episodes of intense vomiting with **normal health between**. Associated with **family history of migraine** (migraine equivalent).", "Treat with hydration, antiemetics, migraine prophylaxis."]}, {"t": 1600, "title": "Upper GI bleeding", "notes": ["Endoscopy shows the bleeding site. Causes: Mallory-Weiss tear, ulcers, varices."]}, {"t": 1870, "title": "Pyloric stenosis", "notes": ["**3 to 6 weeks**, first-born boys. **Nonbilious projectile vomiting**, hungry after vomiting, olive mass.", "**Hypochloremic hypokalemic metabolic alkalosis**. Correct fluids and electrolytes before surgery.", "Ultrasound: **muscle thickness over 4 mm, length over 14 mm**. Treat with pyloromyotomy."]}, {"t": 2150, "title": "Duodenal atresia and annular pancreas", "notes": ["Bilious vomiting on day 1, **polyhydramnios**, **double bubble**. Rare (1 in 10,000). **Down syndrome in 20 to 30%**.", "Look for other anomalies (heart, spine). Correct electrolytes, NG decompression, **surgical repair**.", "Annular pancreas: also obstructs the duodenum, also linked to Down syndrome."]}, {"t": 2420, "title": "Functional constipation", "notes": ["Triggers: toilet training, stress, travel, holding stool. Large hard stools, painful.", "Pain can be dramatic and mimic an acute abdomen. Ask about stooling history.", "**Encopresis** is overflow soiling, not diarrhea."]}, {"t": 2640, "title": "Constipation treatment", "notes": ["Impaction: **clean out first** (enema or PEG through NG), then maintenance.", "Maintenance: **polyethylene glycol daily**, safe long term, plus behaviour (sit 10 minutes after meals) and more water and fibre."]}, {"t": 2820, "title": "Hirschsprung disease", "notes": ["Associated with **Down syndrome**. **No meconium in 48 hours** (99% of healthy term babies pass it).", "Aganglionic segment is narrow, proximal bowel dilated. Explosive stool after rectal exam.", "Complication: **enterocolitis**. Diagnosis: rectal suction biopsy. Treat with resection and pull-through."]}, {"t": 3060, "title": "Anal fissure", "notes": ["Bright red blood on hard stool, painful passage. Treat the constipation, sitz baths."]}, {"t": 3150, "title": "Recurrent abdominal pain and IBS", "notes": ["One of the most common reasons to see a pediatrician, about 15 to 35% of children.", "**Red flags**: weight loss, night waking pain, GI bleeding, fever, family history of IBD, pain away from the umbilicus.", "IBS: cramping pain relieved by stooling, with change in stool frequency or form."]}, {"t": 3480, "title": "Inflammatory bowel disease", "notes": ["Bloody diarrhea, weight loss, growth delay, arthritis. **Ulcerative colitis**: continuous from the rectum. Crohn: skip lesions, perianal disease, ileum.", "**Pyoderma gangrenosum** (looks like a spider bite, then ulcer) and erythema nodosum. Toxic megacolon: plain x-ray first.", "Rule out infection with stool cultures before diagnosing IBD. Diagnosis by colonoscopy with biopsy."]}, {"t": 4320, "title": "Celiac disease", "notes": ["Villous atrophy, crypt hyperplasia, intraepithelial lymphocytes on biopsy.", "Treatment: lifelong **gluten-free diet** (no barley, rye, wheat)."]}, {"t": 4440, "title": "Cystic fibrosis (GI)", "notes": ["CFTR chloride transport defect. **Pancreatic insufficiency in about 90%**.", "Failure to thrive in the first months with **bulky greasy foul stools**: test for CF.", "72-hour fecal fat is the accurate test for fat malabsorption. Sweat chloride for diagnosis. Fat-soluble vitamin deficiency."]}], "tx": false}, {"key": "n_it3gIEwcFSI", "id": "it3gIEwcFSI", "who": "Dr Osama Naga", "title": "Pediatric GI, Part 3: Lower GI, bleeding and liver", "len": 4269, "approx": false, "sys": "gi", "sections": [{"t": 0, "title": "Protein-losing enteropathy", "notes": ["Serum protein lost into the gut: **edema, low albumin and low globulin**.", "Causes: primary **intestinal lymphangiectasia**, Whipple disease (Tropheryma whipplei, treat with antibiotics), lymphoma, radiation, **post-Fontan**, constrictive pericarditis, heart failure, polyps, infections, IBD, milk protein allergy, Ménétrier (CMV).", "**Stool alpha-1 antitrypsin** is not normally in stool, positive means protein-losing enteropathy. Treat the cause."]}, {"t": 200, "title": "Intestinal lymphangiectasia", "notes": ["Blocked intestinal lymph drainage, usually **under 3 years**: **lymphopenia, low albumin, low globulin**.", "Associated with Turner, Noonan, Klippel-Trenaunay-Weber, heart failure. Chylous ascites or effusion, steatorrhea.", "Diagnosis: stool alpha-1 antitrypsin. Treat by replacing long-chain fat with **medium-chain triglycerides**."]}, {"t": 270, "title": "Short bowel syndrome", "notes": ["Loss of over 50% of small bowel: malabsorption, TPN.", "Good odds of weaning TPN: **15 cm with the ileocecal valve**, or 20 cm or more without it. Start **trophic feeds** gradually.", "**Duodenum: iron, folate, calcium**. **Ileum: B12 and bile salts** (and fat-soluble vitamins).", "Late complications: **oxalate kidney stones** (fat binds calcium so oxalate is absorbed), bloody diarrhea from fast feeds, constipation, bacterial overgrowth."]}, {"t": 420, "title": "Small bowel bacterial overgrowth", "notes": ["Suspect with chronic abdominal pain after **gut surgery** or anatomic problems.", "Protections lost: gastric acid, bile and pancreatic enzymes, lactobacillus, mucosal barrier, **ileocecal valve**.", "Bloating, distension, diarrhea, fatigue, **ataxia**. Labs: metabolic acidosis with **high D-lactic acid**.", "Treat with broad-spectrum antibiotics (metronidazole, amoxicillin-clavulanate). Complications: malabsorption, fat-soluble vitamin deficiency."]}, {"t": 573, "title": "Diarrhea clues to the bug", "notes": ["**Reactive arthritis**: Salmonella, Shigella, Yersinia, Campylobacter, Cryptosporidium, C difficile.", "**Guillain-Barré**: Campylobacter. Appendicitis mimic: **Yersinia**. IgA nephropathy: Campylobacter.", "**Erythema nodosum**: Yersinia, Campylobacter, Salmonella. **Hemolytic uremic syndrome**: Shigella dysenteriae, **E coli O157:H7**."]}, {"t": 684, "title": "Dehydration: oral rehydration", "notes": ["Case: 4-year-old, nonbloody diarrhea, mild tachycardia, normal BP and capillary refill, **drinking**: mild to moderate dehydration. **Oral rehydration solution at home**.", "Oral rehydration is best for mild to moderate, **even with vomiting**, as long as the child drinks.", "IV fluids only for **shock, low BP or severe dehydration**."]}, {"t": 820, "title": "Diarrhea management", "notes": ["Viral and most bacterial diarrhea is **self-limited**, no antibiotics.", "**No loperamide** (ileus, toxic megacolon, death). Bismuth risks salicylate toxicity.", "Keep a **regular diet**, but **no juice or sports drinks** (osmotic). Probiotics help. Lasting over 2 weeks: try lactose-free.", "Prolonged viral diarrhea causes lactose intolerance: stool **reducing substances positive, pH under 6**."]}, {"t": 930, "title": "When to give antibiotics", "notes": ["**Shigella**: ciprofloxacin, TMP-SMX or azithromycin. Third-generation cephalosporin if admitted.", "**Salmonella**: only if **under 3 months**, malignancy or immunocompromised (ceftriaxone).", "**C difficile**: metronidazole, again for a recurrence. If it fails: **oral vancomycin only, never IV**.", "Entamoeba: metronidazole, then a luminal agent (paromomycin or iodoquinol)."]}, {"t": 1030, "title": "Toddler's diarrhea", "notes": ["Under 3 years, **lots of juice**. Up to 10 loose stools a day, **no blood or mucus**, healthy and growing, **no stools at night**, undigested food visible.", "Reassure, **cut juice, add fat** to the diet."]}, {"t": 1120, "title": "Secondary lactase deficiency", "notes": ["Villous tip injury after **rotavirus**, parasites, celiac, Crohn. Gas, bloating, osmotic diarrhea.", "Diagnosis: 2-week **lactose-free trial**, hydrogen breath test, stool **pH under 5 and reducing substances**. Treat lactose-free or lactase enzyme."]}, {"t": 1185, "title": "Congenital diarrheas", "notes": ["With **polyhydramnios**: congenital chloride diarrhea (**acidic stool, metabolic alkalosis, low serum chloride, high stool chloride**) and congenital sodium diarrhea (alkaline stool, metabolic acidosis, low serum sodium).", "No polyhydramnios: **microvillous inclusion disease**, watery diarrhea from day 1, villous atrophy without inflammation. Lifelong TPN, intestinal transplant."]}, {"t": 1365, "title": "GI bleeding: upper vs lower", "notes": ["Hematemesis: upper. Bright red blood: lower. Melena or occult blood: either, **NG aspirate** helps.", "First confirm it's blood (guaiac). Mimics: food colouring, juice, **cefdinir** (maroon stool)."]}, {"t": 1440, "title": "GI bleeding by age", "notes": ["Newborn: **swallowed maternal blood** (Apt test, cracked nipples, bloody cesarean), NEC, malrotation, fissure, Hirschsprung colitis.", "Infant: fissure, **milk protein colitis**, infectious colitis, intussusception, Meckel, HUS.", "Older child: **check the nose first (epistaxis)**, gastritis, ulcer, varices, juvenile polyps, infectious colitis, fissure, HSP."]}, {"t": 1550, "title": "GI bleeding: management and Mallory-Weiss", "notes": ["Stabilize first. Tachycardia, hypotension, orthostatic changes, slow capillary refill: significant bleed.", "Swallowed blood (nose, breastfeeding, dental work, tonsillectomy), stress ulcer, varices.", "**Mallory-Weiss**: tear at the gastroesophageal junction from forceful vomiting or retching. Most heal on their own, band if persistent."]}, {"t": 1700, "title": "Gastritis and varices", "notes": ["Diffuse gastritis: trauma, burns, ICU. Localized: **NSAIDs**, alcohol, H pylori. Coffee-ground emesis.", "Varices: most common pediatric cause is **portal vein cavernous transformation (thrombosis)**. Splenomegaly, ascites, jaundice.", "Portal vein thrombosis risks: **umbilical venous catheter**, neonatal sepsis, shock, exchange transfusion. Secondary prevention: acid suppression, sucralfate, sclerotherapy or banding."]}, {"t": 1786, "title": "Meckel diverticulum", "notes": ["Vitelline duct remnant in the ileum with **ectopic gastric mucosa** making acid that ulcerates nearby ileum.", "Rule of 2s: 2%, 2 feet from the ileocecal valve, 2 inches long, usually under 2 years.", "Classic: **significant painless rectal bleeding** (Meckel until proven otherwise). Can be painful. Anemia, hypovolemia, **lead point for intussusception**, appendicitis mimic.", "**Meckel (Tc-99m) scan** is the best first test, but **a negative scan doesn't rule it out** (capsule may miss it too). Treatment: surgery."]}, {"t": 2070, "title": "Juvenile polyps and polyposis", "notes": ["Most common childhood polyp, age **2 to 10**. **Bright red painless bleeding right after stooling**, may prolapse as a dark red mass. Colonoscopy and removal.", "**Juvenile polyposis**: over 5 polyps, autosomal dominant. Bleeding, intussusception, failure to thrive, anemia, low albumin. Cancer risk rises with more polyps or family history."]}, {"t": 2170, "title": "Gardner syndrome", "notes": ["Autosomal dominant: **polyps with osteomas**, epidermoid cysts, dental abnormalities. Polyps are premalignant (small bowel, colon, stomach)."]}, {"t": 2195, "title": "Liver tests: what they mean", "notes": ["**PT and albumin are the true liver function tests**. PT prolonged and **not fixed by IV vitamin K** means liver failure.", "AST and ALT can be in the thousands with a healthy liver (virus, acetaminophen). They are the most sensitive markers of hepatocyte damage, not function.", "Any **direct hyperbilirubinemia is pathologic**: cholestasis, biliary atresia.", "High AST and ALT from muscle: **Duchenne**, check **CK**.", "**Shrinking liver, falling AST and ALT, rising PT** that doesn't correct with vitamin K: liver failure, transplant."]}, {"t": 2433, "title": "Alkaline phosphatase and GGT", "notes": ["High ALP: obstructive liver disease, **growth spurts**, **rickets**, fractures, **transient hyperphosphatasemia of infancy**, bowel disease.", "**High ALP with normal GGT: bone, not liver**. GGT doesn't rise in bone disease, is normally high in newborns."]}, {"t": 2565, "title": "Causes of jaundice", "notes": ["Unconjugated: hemolysis, Gilbert, Crigler-Najjar, **hypothyroidism**, UTI and sepsis.", "Conjugated: infection (TORCH, **UTI**, sepsis), metabolic (**alpha-1 antitrypsin, CF, galactosemia**), obstructive (**biliary atresia, choledochal cyst**), Alagille, PFIC, hypothyroidism, TPN, shock and heart failure."]}, {"t": 2670, "title": "Gilbert vs Crigler-Najjar", "notes": ["**Gilbert**: low UGT, mild indirect bilirubin **under 5**, worse with **fasting, fever, exercise**. Reassure.", "**Crigler-Najjar type 1**: **no UGT**, bilirubin 20 to 50, day 1, **kernicterus**. Phototherapy, then liver transplant.", "Type 2: partial UGT, bilirubin 7 to 20, well. Reassure (responds to phenobarbital)."]}, {"t": 2775, "title": "Alpha-1 antitrypsin deficiency", "notes": ["**Most common genetic cause of liver disease in children**. Prolonged jaundice and neonatal hepatitis, hepatomegaly.", "Later: portal hypertension, varices, cirrhosis, hepatocellular carcinoma in adults. Confirm with liver biopsy and phenotype."]}, {"t": 2815, "title": "Wilson disease", "notes": ["Autosomal recessive copper buildup in **liver and brain**. Think of it with **unexplained liver disease plus neuro or psychiatric change** (depression, psychosis, school decline).", "Tremor, dysarthria, dystonia, **Kayser-Fleischer rings**, **hemolytic anemia** can be first.", "**Low ceruloplasmin (under 20)**, urine copper over 100 µg/day, liver biopsy. Treat: low copper diet, **penicillamine**. Fatal if missed."]}, {"t": 2905, "title": "Neonatal cholestasis", "notes": ["Most common cause in preemies: **TPN**. Most common congenital infection: **CMV**.", "**Jaundice still present at 2 weeks: check direct bilirubin**. Pale or clay stools and hepatomegaly add concern.", "Workup: direct bilirubin, AST, ALT, **ALP and GGT (obstruction)**, urinalysis and culture, **urine reducing substances and eye exam for cataract (galactosemia)**, CF and thyroid screen.", "Advanced injury: **PT not corrected by vitamin K**, high ammonia, low albumin, hypoglycemia."]}, {"t": 3080, "title": "Biliary atresia", "notes": ["Obliteration of extrahepatic ducts. **Most common cause of neonatal cholestasis**.", "Feeds and grows well, jaundice, **acholic stools**: investigate urgently.", "**Ultrasound first** (also finds choledochal cyst). Biopsy: duct proliferation, inflammation, fibrosis, bile plugs. **Gold standard: intraoperative cholangiogram**.", "**Kasai before 60 days** gives the best flow, poor after 90 days."]}, {"t": 3215, "title": "Congenital hepatic fibrosis and Alagille", "notes": ["Congenital hepatic fibrosis: autosomal recessive, with **autosomal recessive polycystic kidney disease**. Presents with **portal hypertension and varices**.", "**Alagille**: autosomal dominant **JAG1**. **Paucity of bile ducts** (cholestasis), **peripheral pulmonary stenosis**, **butterfly vertebrae**, **posterior embryotoxon**, broad forehead with pointed chin."]}, {"t": 3300, "title": "Hepatomegaly and its workup", "notes": ["Newborn liver edge over **3.5 cm** below the costal margin, child over **2 cm**.", "Causes: hepatitis (viral, autoimmune, drugs like acetaminophen), Wilson, Budd-Chiari, fatty liver, heart failure, storage disease (glycogen, mucopolysaccharidoses).", "Labs: CBC, retic, chemistry, fractionated bilirubin, ESR, GGT, **PT**, hepatitis serology, alpha-1 antitrypsin, AFP, **ceruloplasmin**, ANA, anti-smooth muscle, anti-LKM, sweat chloride, lipids."]}, {"t": 3405, "title": "Hepatitis A", "notes": ["Fecal-oral (food, travel). Often asymptomatic, then malaise, fever, vomiting, jaundice. Supportive, **avoid acetaminophen**.", "Vaccine at **12 and 18 months** (2 doses 6 months apart). Travellers over 1 year: vaccine before travel. **Under 1 year: immunoglobulin**.", "Post-exposure immunoglobulin for long exposures (daycare, household), not school or work."]}, {"t": 3515, "title": "Hepatitis B and its serology", "notes": ["Blood and sexual spread, **not by kissing, hugging or sharing utensils**.", "**HBsAg**: infection. **Anti-HBc**: infection. **Anti-HBs alone: vaccinated**. **Anti-HBs plus anti-HBc: past infection, resolved**.", "**HBeAg**: replication and infectivity. Anti-HBe: improving, the goal of therapy."]}, {"t": 3720, "title": "Hepatitis B treatment and prevention", "notes": ["Supportive. Interferon or lamivudine are approved.", "**Routine vaccination**. Kids with hepatitis B can attend school or daycare unless they bite.", "**HBIG** for babies of HBsAg-positive mothers. Preterms under 2 kg need a **4th dose**. Low titres after vaccination are still protected."]}, {"t": 3810, "title": "Hepatitis C", "notes": ["Leads to cirrhosis and cancer. Genotype 1 is hardest to treat.", "Associated: **membranoproliferative glomerulonephritis**, ITP.", "Babies of infected mothers: only **5% infected**, 30% of those clear it. **HCV RNA at 1 to 2 months**, or **anti-HCV at 18 months or later** (maternal antibody before). Direct-acting antivirals."]}, {"t": 3990, "title": "Autoimmune hepatitis", "notes": ["Presents like viral hepatitis with **negative viral serology**. Splenomegaly, other autoimmune disease in the family.", "AST and ALT can be in the thousands, **high gamma globulin with low albumin**, prolonged PT.", "Antibodies: **anti-smooth muscle, ANA, anti-LKM**. Treat with **prednisone and azathioprine**, fast response."]}], "tx": true}, {"key": "n_t95Rjxn1X8w", "id": "t95Rjxn1X8w", "who": "Dr Osama Naga", "title": "Pediatric Cardiology, Part 1: Chest pain, syncope, murmurs, heart failure", "len": 1424, "approx": false, "sys": "cv", "sections": [{"t": 0, "title": "Case: exertional chest pain with ST changes", "notes": ["15-year-old with chest pain **during exertion** (not before or after) and ST elevation: **anomalous coronary artery**, a major cause of sudden death in athletes."]}, {"t": 105, "title": "Chest pain: causes", "notes": ["Most pediatric chest pain is **non-cardiac**. **Idiopathic** is most common (20 to 45%), reassure.", "Cardiac (rare): coronary disease (**homozygous familial hypercholesterolemia**), **past Kawasaki** (aneurysm), anomalous coronary, **cocaine**, pericarditis, myocarditis, SVT, aortic stenosis, **Marfan dissection**, HCM, pulmonary hypertension."]}, {"t": 225, "title": "Red flags for cardiac chest pain", "notes": ["Pain or **syncope with exertion or swimming**, exertional dyspnea, palpitations before the pain, family history of **HCM** or sudden death. Babies: poor feeding, fussiness."]}, {"t": 260, "title": "Non-cardiac chest pain", "notes": ["**Musculoskeletal**: chest wall tenderness, NSAIDs and reassurance.", "**Exercise-induced asthma**: chest tightness without cough, lungs clear in clinic. **Salbutamol before exercise** is diagnostic and therapeutic.", "Also pneumonia, anxiety and stress, reflux, **sickle cell acute chest**."]}, {"t": 350, "title": "Vasovagal syncope", "notes": ["Case: 13-year-old faints **while standing** after lightheadedness, nausea, pallor, sweating, recovers lying down: vasovagal. **Reassure, no ECG or labs**.", "Fainting **lying down, while running or swimming** is abnormal.", "Treatment: **more fluid and salt**. Recurrent: fludrocortisone, midodrine, beta blockers, pacemaker for documented bradycardia."]}, {"t": 510, "title": "Cardiac syncope: red flags and workup", "notes": ["Causes: **HCM**, aortic stenosis, coronary anomalies, VT, complete heart block. Non-cardiac: seizure, hypoglycemia, psychogenic.", "Red flags (refer to cardiology): palpitations, dyspnea or chest pain first, syncope **with exercise, swimming or supine**, **startle-triggered** (long QT), age under 10, heart disease, family history of cardiomyopathy or channelopathy, abnormal exam, **bradycardia**.", "First test **ECG** (long QT, ventricular hypertrophy), then Holter or event monitor, echo if exam or ECG abnormal."]}, {"t": 650, "title": "Innocent murmur", "notes": ["Case: 4-year-old, **1/6 low-pitched vibratory systolic** murmur at the left sternal border, **softer sitting up**: innocent (Still's) murmur.", "Innocent murmurs: **always systolic**, grade 1 to 2, musical, louder supine, no radiation.", "Mitral and tricuspid: stenosis is diastolic, regurgitation systolic. Aortic and pulmonary: stenosis systolic, regurgitation diastolic."]}, {"t": 745, "title": "How to listen and benign murmurs", "notes": ["Listen supine then sitting, then the back. Grade 1 to 6, timing, location of maximum intensity, radiation, pitch.", "**Peripheral pulmonary stenosis of the newborn**: soft systolic at the left upper sternal border, **radiates to both axillae and back**, gone by 3 to 6 months.", "**Venous hum**: continuous, right infraclavicular, sitting up, **disappears lying down or with jugular pressure**."]}, {"t": 923, "title": "Pathologic murmurs", "notes": ["Systolic ejection: **aortic stenosis** (right upper sternal border), pulmonary stenosis (left upper), **ASD** (left upper, flow), coarctation (left clavicle and back).", "Holosystolic: **VSD** (harsh, left lower sternal border), mitral regurgitation (blowing, apex to left axilla), tricuspid regurgitation.", "Early diastolic: aortic regurgitation (leaning forward). Mid-diastolic rumble: mitral stenosis.", "Continuous: **PDA** (left infraclavicular, machinery), coronary fistula."]}, {"t": 1095, "title": "Case: heart failure in Down syndrome", "notes": ["5-month-old with trisomy 21, RR 70, **clear lungs**, sats 85%, 3/6 holosystolic murmur, liver 4 cm: **heart failure** from a congenital defect (AV canal or VSD). Next step: **furosemide**.", "**Tachypnea with clear lungs and a murmur**: think cardiac, not bronchiolitis. 40 to 50% of Down syndrome have heart disease."]}, {"t": 1230, "title": "Heart failure: causes and presentation", "notes": ["Left-to-right shunts (VSD, AV canal, PDA) present at **1 to 3 months** as pulmonary resistance falls. **Oxygen can make it worse**.", "Low output: dilated cardiomyopathy, neonatal aortic stenosis or coarctation, restrictive or hypertrophic cardiomyopathy, pericardial effusion, SVT.", "Picture: poor growth, **sweating and tiring with feeds**, tachypnea, grunting, hepatomegaly, gallop. Older kids: exercise intolerance, abdominal pain."]}, {"t": 1340, "title": "Heart failure: workup and treatment", "notes": ["Pulse oximetry, chest x-ray, echo, **BNP**, troponin.", "Treat the cause. **Diuretics (furosemide)** for overload, milrinone or nitroprusside, ACE inhibitors and beta blockers for remodelling."]}], "tx": true}, {"key": "n_sBjdf0bZA4c", "id": "sBjdf0bZA4c", "who": "Dr Osama Naga", "title": "Pediatric Cardiology, Part 2: Congenital heart defects", "len": 1637, "approx": false, "sys": "cv", "sections": [{"t": 36, "title": "History and exam in suspected heart disease", "notes": ["Timing: **severe coarctation presents with heart failure in week 1**, large left-to-right shunts at **6 to 8 weeks**.", "Maternal diabetes: **hypertrophic cardiomyopathy**. Lithium: **Ebstein anomaly**.", "Four-limb pulses and BP, S2 (single or widely split). Not all cyanosis is cardiac: tension pneumothorax."]}, {"t": 132, "title": "Murmur myths and red flags", "notes": ["Murmur in the first hours can be a **closing ductus** (benign). VSD or AV canal may have **no murmur at birth**. ASD is repaired around school age.", "Heart disease mimics sepsis in newborns (coarctation, hypoplastic left heart).", "Red flags: **unexplained metabolic acidosis**, poor perfusion, **arm vs leg pulse difference**, **single S2**, loud S2, hyperactive precordium, shock. Call cardiology."]}, {"t": 226, "title": "Acyanotic left-to-right shunts", "notes": ["**VSD is most common**, then PDA, ASD, AV canal (**trisomy 21**).", "Increased pulmonary vascularity on x-ray. Heart failure at **4 to 6 weeks** as pulmonary resistance falls. **Oxygen worsens it**.", "Untreated: **Eisenmenger** (early with AV canal, years with ASD).", "**Echo every baby with suspected trisomy 21**, murmur or not."]}, {"t": 396, "title": "Cyanotic defects by lung markings", "notes": ["**Decreased pulmonary markings**: tetralogy of Fallot, tricuspid atresia, Ebstein, pulmonary atresia, Eisenmenger.", "**Increased markings**: transposition, TAPVR, truncus arteriosus."]}, {"t": 460, "title": "Hyperoxia test and prostaglandin", "notes": ["Give **100% oxygen** and check arterial PaO2. Lung disease rises to **100 mmHg or more**. Cardiac stays below 100.", "Ductal-dependent lesions: start **prostaglandin E1**. Side effects: **apnea**, flushing."]}, {"t": 525, "title": "22q11 deletion screening", "notes": ["Screen any baby with **conotruncal defects** (truncus arteriosus, tetralogy, interrupted aortic arch, pulmonary atresia with VSD), even without DiGeorge features.", "Preferred test: **chromosomal microarray**. FISH misses small deletions."]}, {"t": 575, "title": "Shock or heart failure in week 1", "notes": ["Poor perfusion, metabolic acidosis, hepatomegaly, gallop in the first week: **left-sided obstruction**: **severe coarctation, hypoplastic left heart, interrupted aortic arch**.", "**Prostaglandin to open the ductus** and urgent cardiology."]}, {"t": 620, "title": "Reading the pediatric chest x-ray", "notes": ["Cardiothoracic ratio **over 55% is cardiomegaly**.", "Prominent aortic knob: aortic stenosis. Prominent pulmonary artery: left-to-right shunt. Left atrial enlargement: wide carina, double density. Upturned apex: right ventricle. Downward apex: left ventricle.", "ASD: big RA, RV, pulmonary artery. Tetralogy: big RV, small pulmonary arteries, **boot-shaped heart**. PDA and VSD: big LA, LV. **Coarctation: rib notching**."]}, {"t": 860, "title": "X-ray cases", "notes": ["2-month-old, cardiomegaly, increased markings: **VSD or PDA**.", "Cyanotic spells, narrow mediastinum, upturned apex, low markings: **tetralogy of Fallot**.", "Cyanosis in the first hours, single loud S2, **egg on a string**, increased markings: **transposition**. Prostaglandin.", "Huge heart filling the chest, clear lungs: **Ebstein anomaly**.", "**Snowman** heart, recurrent lung infections: **supracardiac TAPVR**."]}, {"t": 1095, "title": "ECG findings", "notes": ["Tall R in V1, deep S in V6, **upright T in V1 after 1 week**: right ventricular hypertrophy (tetralogy, pulmonary hypertension).", "**Superior axis (negative aVF)**: **AV canal**, primum ASD, tricuspid atresia.", "Right bundle branch block (wide QRS, RSR' in V1): **after heart surgery** (repaired tetralogy), Ebstein, primum ASD.", "**WPW**: short PR, wide QRS, **delta wave**."]}, {"t": 1355, "title": "Review: transposition and TAPVR", "notes": ["Transposition: give **prostaglandin first**. Echo is for surgical planning, not an emergency first step.", "**Obstructed infradiaphragmatic TAPVR**: severe distress and cyanosis right after birth, looks like RDS or GBS pneumonia. **Surgical emergency**."]}, {"t": 1485, "title": "Heart failure by age", "notes": ["Week 1: **left-sided obstruction** (prostaglandin). 6 to 8 weeks: **left-to-right shunt**. Older child: myocarditis, rheumatic heart disease."]}, {"t": 1520, "title": "Syndromes and heart defects", "notes": ["**Trisomy 21**: AV canal, VSD. **Turner**: **bicuspid aortic valve**, coarctation, lifelong follow-up for dissection. Trisomy 13 and 18: VSD. Noonan: **pulmonary stenosis**.", "**Williams**: **supravalvar aortic stenosis**, peripheral pulmonary stenosis, **hypercalcemia**, friendly personality. Holt-Oram: ASD with arm and hand defects.", "Lithium: Ebstein. Alcohol: ASD, VSD. Retinoic acid and maternal diabetes: transposition (diabetes also HCM). **Maternal lupus: congenital heart block**."]}], "tx": true}, {"key": "n_WiXGhrO49kU", "id": "WiXGhrO49kU", "who": "Dr Osama Naga", "title": "Simplified Pediatric ECG Interpretation", "len": 3051, "approx": false, "sys": "cv", "sections": [{"t": 0, "title": "ECG paper and waves", "notes": ["Small square **40 ms**, large square **200 ms**, 300 large squares per minute. Standard: 10 mm amplitude, 25 mm/s.", "P: atrial depolarization. PR: AV conduction. QRS: ventricular depolarization. ST and T: repolarization. QT: whole ventricular cycle."]}, {"t": 129, "title": "Leads and normal variation by age", "notes": ["Lateral: I, aVL, V5, V6. Inferior: II, III, aVF. V1 and V2 see the right ventricle, V5 and V6 the left.", "**T wave upright in V1 is normal only in the first week**, then suggests RV hypertrophy (normal again after about 6 to 7 years).", "Newborns: big R in V1 that shrinks with age."]}, {"t": 293, "title": "Systematic approach, rate and axis", "notes": ["Order: rhythm, rate, axis, P wave and PR, QRS, QT, ST, T.", "Rate: **300 divided by large squares between R waves** (or R waves in 10 seconds times 6).", "Axis from I and aVF: both positive normal, I positive aVF negative **left**, I negative aVF positive **right**. **Newborns normally have right axis deviation**."]}, {"t": 488, "title": "Atrial enlargement", "notes": ["**Tall peaked P over 3 mm** in II: right atrial enlargement.", "**Broad notched P over 120 ms** in II or deep negative P in V1: left atrial enlargement."]}, {"t": 625, "title": "PR interval and heart block", "notes": ["PR under 200 ms (under 130 ms in newborns).", "**First degree**: long PR, every P conducts. **Mobitz I (Wenckebach)**: PR lengthens until a dropped QRS. **Mobitz II**: normal PR, sudden dropped QRS.", "**Third degree**: P and QRS independent, bradycardia (e.g. after heart surgery)."]}, {"t": 830, "title": "Heart block management", "notes": ["Observe first degree and Mobitz I.", "Mobitz II and complete block with symptomatic bradycardia: **transcutaneous or transvenous pacing**. **Atropine is the wrong answer for complete heart block** (can worsen it). Permanent pacemaker may be needed."]}, {"t": 866, "title": "QRS: ventricular hypertrophy", "notes": ["QRS normally under 120 ms. Always compare to **age norms**.", "**Tall R in V1 and deep S in V6**: right ventricular hypertrophy. Deep S in V1 and tall R in V6: left ventricular hypertrophy."]}, {"t": 1050, "title": "Right bundle branch block", "notes": ["Common in kids **after open heart surgery** (repaired tetralogy).", "**Wide QRS over 120 ms with RSR' in V1**, wide S in V6."]}, {"t": 1112, "title": "Premature atrial and ventricular contractions", "notes": ["**PACs**: early beat with an odd P wave and normal QRS. Very common in newborns. **Reassure**, avoid caffeine.", "**PVCs**: early beat with **no P and a wide bizarre QRS**. Benign if **uniform, suppressed by exercise**, normal heart, no family history of sudden death.", "Refer: multiform PVCs, **worse with exercise**, structural disease, family history, or symptoms. Can be first sign of myocarditis."]}, {"t": 1368, "title": "QT interval and long QT", "notes": ["**QTc = QT / square root of RR** (in seconds). Normal up to 0.44 s (up to 0.49 s under 6 months).", "Case: teen faints **playing football**, QT more than half the RR: **long QT**.", "Causes: **tricyclics**, macrolides, TMP-SMX, **low calcium, magnesium, potassium**, ion channel genes."]}, {"t": 1490, "title": "Long QT syndromes and treatment", "notes": ["**Jervell and Lange-Nielsen: long QT with congenital deafness**. Romano-Ward: no deafness.", "Ask about family sudden death and deafness. Fainting with **swimming, startle, exercise**, seizures, 10% sudden arrest.", "Newborn fails hearing screen with very long QT: **Jervell and Lange-Nielsen**. Treat with **beta blockers**, ICD for high risk, avoid QT-prolonging drugs."]}, {"t": 1735, "title": "Atrial flutter", "notes": ["**Sawtooth** flutter waves (II, III, aVF), atrial rate 300 to 400, usually 2:1 conduction, regular RR.", "Infants: heart failure. Over 24 to 48 hours: risk of atrial clot.", "**Synchronized cardioversion** if no clot (or if unstable). Chronic: anticoagulate 2 to 4 weeks first. Ablation can cure."]}, {"t": 1880, "title": "Atrial fibrillation", "notes": ["**Irregularly irregular**, no clear P waves.", "Causes: other SVTs, **hyperthyroidism**, low magnesium, **cocaine**, HCM, ASD.", "Urgent cardiology. Unstable: synchronized cardioversion."]}, {"t": 1980, "title": "Supraventricular tachycardia", "notes": ["**Narrow complex**, fixed rate with **no beat-to-beat variation**, P waves hidden in the T.", "Infants: **220 to 270**, poor feeding, irritability, heart failure if prolonged. Children 180 to 240, palpitations. A crying baby at 180 that settles is not SVT.", "Stable: **vagal manoeuvres (ice to the face)**, then **IV adenosine**. **No verapamil under 1 year** (shock). No digoxin in WPW. Unstable: **synchronized cardioversion**. Recurrent: ablation."]}, {"t": 2215, "title": "Wolff-Parkinson-White", "notes": ["Accessory pathway: **short PR, delta wave, wide QRS**.", "Associated with **Ebstein anomaly**, cardiomyopathy, corrected transposition."]}, {"t": 2375, "title": "Tricyclic overdose ECG", "notes": ["Sinus tachycardia, long PR, QRS and QTc.", "**QRS over 100 ms: give sodium bicarbonate**."]}, {"t": 2410, "title": "Ventricular tachycardia", "notes": ["3 or more beats of **wide bizarre QRS**, regular, T opposite the QRS.", "Causes: drugs (**decongestants**, caffeine), electrolytes, heart disease, post-surgery, cardiomyopathy.", "**Emergency**: check stability first. Then echo, stress test, Holter."]}, {"t": 2585, "title": "Ventricular fibrillation", "notes": ["Chaotic waves, no P or QRS, **no pulse**. Start ACLS and **defibrillate (unsynchronized)**."]}, {"t": 2645, "title": "ST elevation: pericarditis", "notes": ["Chest pain worse **lying flat and with inspiration**, **diffuse ST elevation in all leads**: pericarditis.", "Focal ST changes: rare ischemia (anomalous coronary, familial hypercholesterolemia)."]}, {"t": 2747, "title": "T waves and sinus arrhythmia", "notes": ["**Peaked T waves: hyperkalemia** (then long PR, lost P, wide QRS as potassium rises). Flat T: hypokalemia, hypothyroidism.", "**Sinus arrhythmia**: rate rises with inspiration, falls with expiration. Normal, reassure."]}], "tx": true}, {"key": "n_m1KhN5hhooA", "id": "m1KhN5hhooA", "who": "Dr Osama Naga", "title": "Renal Disorders I", "len": 1856, "approx": false, "sys": "renal", "sections": [], "tx": false}, {"key": "n_CB8DiBldnKY", "id": "CB8DiBldnKY", "who": "Dr Osama Naga", "title": "Renal Disorders II", "len": 2302, "approx": false, "sys": "renal", "sections": [], "tx": false}, {"key": "n_sP3o0qcPoGM", "id": "sP3o0qcPoGM", "who": "Dr Osama Naga", "title": "Renal Disorders, Part 3: Tubular disease, cysts, AKI, enuresis, hypertension", "len": 2572, "approx": false, "sys": "renal", "sections": [{"t": 0, "title": "Nephrogenic diabetes insipidus", "notes": ["Distal nephron **ignores ADH**: dilute urine, **hypernatremia**, high serum osmolality. 90% **X-linked recessive**. Secondary: drugs, pyelonephritis, obstruction, **sickle cell trait**.", "Vague in infants: poor feeding, failure to thrive, irritability, constipation. Breastfed babies are diagnosed later (lower solute load).", "Red flags: can't toilet train, daytime accidents, **constant thirst**, dilated bladder on ultrasound."]}, {"t": 205, "title": "DI diagnosis and treatment", "notes": ["**Vasopressin test**: urine concentrates in central DI, **no change in nephrogenic**. ADH normal or high in nephrogenic, low in central.", "Sodium up to 170, serum osmolality over 300.", "**Never restrict water**. Low sodium and protein diet, **thiazide** and **indomethacin** reduce water loss."]}, {"t": 323, "title": "Bartter syndrome", "notes": ["**Loop of Henle** defect (like a loop diuretic). Can start **in utero with polyhydramnios**, triangular face, polyuria, failure to thrive.", "**High renin and aldosterone with normal or low BP**. **Hypokalemic hypochloremic metabolic alkalosis**, **hypercalciuria** (stones), low magnesium in 30%, high urine chloride and prostaglandins.", "Treat: fluids, potassium, spironolactone, ACE inhibitor, **indomethacin**, growth hormone."]}, {"t": 420, "title": "Bartter vs Gitelman", "notes": ["Gitelman: **distal tubule** (like a thiazide), presents in late childhood to adulthood with cramps, numbness, fatigue. Growth delay is a Bartter feature.", "Both: hypokalemic hypochloremic metabolic alkalosis. **Urine calcium high in Bartter, low in Gitelman**. Magnesium **always low in Gitelman**."]}, {"t": 486, "title": "Polycystic kidney disease", "notes": ["**Autosomal recessive**: oligohydramnios, **pulmonary hypoplasia, Potter facies**, bilateral flank masses in newborns, **hepatic fibrosis with portal hypertension**, cholangitis.", "**Autosomal dominant**: adults, hematuria, flank masses, hypertension, cysts in liver, pancreas, spleen, **intracranial aneurysms**. No family history doesn't rule it out (new mutations)."]}, {"t": 552, "title": "Nephronophthisis and Bardet-Biedl", "notes": ["Nephronophthisis: medullary cysts, early **polyuria, thirst, fatigue**, anemia (low EPO). **End-stage kidney disease around age 13**. Joubert (oculomotor apraxia, retinitis pigmentosa, ataxia). Ultrasound: lost corticomedullary differentiation.", "**Bardet-Biedl** (Laurence-Moon-Bardet-Biedl): obesity, **retinitis pigmentosa**, hypogonadism, **polydactyly**, intellectual disability, cystic dysplastic kidneys."]}, {"t": 645, "title": "Multicystic dysplastic kidney", "notes": ["Renal mass is the most common newborn abdominal mass: **hydronephrosis first, MCDK second**. Bilateral is fatal.", "Confirm with ultrasound, then **VCUG** (30 to 50% have reflux in the other kidney).", "**Serial ultrasounds**: the kidney should shrink. If it grows, refer for nephrectomy. Normal life expectancy, **avoid contact sports**."]}, {"t": 730, "title": "Acute kidney injury: types", "notes": ["Rapid fall in filtration: rising creatinine and BUN, oliguria.", "**Prerenal**: low perfusion (**gastroenteritis and dehydration most common**, heart failure, sepsis). **Postrenal**: obstruction. **Intrinsic**: HUS, rhabdomyolysis, aminoglycosides."]}, {"t": 800, "title": "Prerenal and postrenal indices", "notes": ["Healthy tubules hold on to sodium and water: **urine sodium under 10 to 20, FENa under 1%** (under 2% in newborns), **urine osmolality over 400** (over 350 in newborns), **BUN to creatinine over 20**.", "Untreated prerenal or long obstruction turns into intrinsic injury."]}, {"t": 1000, "title": "Intrinsic AKI indices", "notes": ["Damaged tubules: **FENa over 2%** (over 2.5% in newborns), high urine sodium, **dilute urine**, **BUN to creatinine under 15**.", "Sloughed tubule cells: **muddy brown granular casts**."]}, {"t": 1210, "title": "AKI staging, workup and management", "notes": ["Failure: creatinine 3 times baseline or urine under 0.5 mL/kg/h. Over 4 weeks: loss of function. Over 3 months: end-stage disease.", "Labs: BMP, urinalysis, **urine sodium**. Renal ultrasound for anatomy.", "Prevent: hydration with NSAIDs, monitor **gentamicin and vancomycin levels**. Bolus **20 mL/kg** (10 mL/kg if cardiac). Treat acidosis and hyperkalemia (watch T waves and QRS, insulin and glucose).", "**Dialysis**: fluid overload over 10 to 20%, severe acidosis, hyperkalemia, **BUN over 100** or symptomatic uremia."]}, {"t": 1385, "title": "Intrinsic AKI keywords", "notes": ["Muddy brown casts: **acute tubular necrosis** (aminoglycosides, methotrexate, contrast, myoglobin).", "Hematuria **2 to 3 weeks after strep**, hypertension, **low C3, normal C4**: post-infectious GN.", "Gross hematuria **during a URI (1 to 3 days)**, **normal C3 and C4**: IgA nephropathy.", "Rash, arthritis, serositis, **low C3 and C4**, ANA and anti-dsDNA: lupus nephritis."]}, {"t": 1470, "title": "Vasculitis and other intrinsic causes", "notes": ["Hemoptysis plus **anti-GBM**: Goodpasture. Sinusitis, epistaxis, **c-ANCA**: granulomatosis with polyangiitis. Lungs plus **p-ANCA**: microscopic polyangiitis. Asthma, eosinophilia, p-ANCA: eosinophilic granulomatosis (Churg-Strauss).", "Fast loss of function with **crescents** on biopsy: rapidly progressive GN, emergency biopsy.", "**Fever, rash, eosinophilia** with urine eosinophils and WBC casts: **allergic interstitial nephritis**.", "Bloody diarrhea, anemia, low platelets, schistocytes, high LDH: **diarrhea-positive HUS** (Shiga toxin E coli)."]}, {"t": 1592, "title": "Nocturnal enuresis: definition and workup", "notes": ["Strong family history. More common in boys. Usually dry by about 6 in girls, 8 in boys.", "Diagnosis of exclusion. History of evening fluids, daytime voiding, number of wet nights.", "**Urinalysis first**: glucose (diabetes), **low specific gravity (DI)**, WBC or positive culture (UTI)."]}, {"t": 1678, "title": "Enuresis differential", "notes": ["Overactive bladder: urgency, crossing legs, **squatting with heel in the perineum**. Neurogenic bladder, small bladder capacity, nocturnal polyuria, cystitis.", "**Obstructive sleep apnea**: removing tonsils and adenoids can cure it. Seizures. **Ectopic ureter: never dry**. Constipation, diabetes mellitus or insipidus.", "Expected bladder capacity = **30 mL + (age x 30 mL)**. Nocturnal polyuria if night urine over 130% of that."]}, {"t": 1786, "title": "Enuresis treatment", "notes": ["Reassure, self-limited. Restrict **evening** fluids but hydrate in the day. No treatment before age 6. Reward dry nights, never punish.", "**First line: bed-wetting alarm**, 8 to 12 weeks. Then **desmopressin** at bedtime: **no drinking after the dose** (hyponatremia, seizures).", "Overactive bladder: **oxybutynin** (anticholinergic). Sleep apnea: lateral neck x-ray, ENT."]}, {"t": 2010, "title": "Hypertension: measuring", "notes": ["Case: 12-year-old with repeat BP 128/77, **over the 95th percentile**: hypertension.", "Rest 5 minutes, bare arm at heart level, child calm. **Bladder length 80 to 100% and width 40% of mid-arm circumference**. Too small a cuff reads falsely high.", "Confirm with a **manual reading on 3 occasions**. Not in hospitalized children."]}, {"t": 2195, "title": "Hypertension: causes", "notes": ["**Before puberty: mostly secondary**. After puberty: mostly essential, but look for a cause at any age.", "Chest pain or murmur: coarctation. Weight loss, sweating, flushing: hyperthyroidism, **pheochromocytoma**, CAH. Headache, papilledema: brain tumour. Rash, joints: lupus.", "Echo for coarctation. Renal ultrasound: masses (Wilms, neuroblastoma), polycystic or small kidneys.", "Drugs: steroids, **decongestants and cold medicines**, NSAIDs, OCPs, stimulants, isotretinoin."]}, {"t": 2340, "title": "Syndromes and treatment of hypertension", "notes": ["Williams: supravalvar aortic stenosis, renal artery stenosis. Turner: coarctation. Tuberous sclerosis, **neurofibromatosis (renal artery stenosis)**, polycystic kidneys.", "Lifestyle: weight loss, **1 hour of exercise daily**, screen time under 2 hours, less salt and sugary drinks.", "First line drugs: **ACE inhibitors or calcium channel blockers** (also ARBs, beta blockers, diuretics). Start low, add a second agent if needed."]}], "tx": true}, {"key": "n_SrtvlSsJzrU", "id": "SrtvlSsJzrU", "who": "Dr Osama Naga", "title": "Dehydration, fluids and electrolytes", "len": 3076, "approx": false, "sys": "renal", "sections": [], "tx": false}, {"key": "n_cU8dxV6IVTA", "id": "cU8dxV6IVTA", "who": "Dr Osama Naga", "title": "Endocrine Disorders", "len": 9239, "approx": false, "sys": "endo", "sections": [], "tx": true}, {"key": "n_CMWg4O8_TGY", "id": "CMWg4O8_TGY", "who": "Dr Osama Naga", "title": "Metabolic Disorders", "len": 2365, "approx": false, "sys": "endo", "sections": [], "tx": true}, {"key": "n_DoQLH82QVZI", "id": "DoQLH82QVZI", "who": "Dr Osama Naga", "title": "Pediatric Respiratory Disorders", "len": 7504, "approx": false, "sys": "pulm", "sections": [{"t": 0, "title": "Spirometry basics", "notes": ["Full breath in, blow out as hard as possible for at least 6 seconds, repeat 3 times, take the best.", "**FVC** normal or slightly low in asthma, **low in restrictive disease**. **FEV1** low in both.", "**FEV1/FVC ratio separates them**: low in asthma (obstruction), normal or high in restrictive disease.", "**FEF 25-75** is the most sensitive marker of obstruction, may be the only abnormal value in mild asthma."]}, {"t": 267, "title": "Volume-time curve and flow-volume loop", "notes": ["Normal: 75% of FVC out in the first second. Asthma: slower, FVC usually normal.", "Flow-volume loop: **scooped (concave) expiratory limb in asthma**, deeper scoop means more severe.", "**Flattened inspiratory limb: variable extrathoracic obstruction** (vocal cord paralysis or dysfunction).", "Restrictive: **normal shape but small loop**."]}, {"t": 554, "title": "Reading a spirometry report", "notes": ["Start with **FEV1/FVC**. Low: obstruction. Normal or high: check FVC (normal = normal lung, low = restrictive).", "Asthma: low ratio, normal FVC, low FEF 25-75. **Reversibility: 12% or more rise in FEV1** after bronchodilator."]}, {"t": 986, "title": "Pulse oximetry and blood gases", "notes": ["False readings: nail polish, dyes, bright light, **poor perfusion** (shock, hypothermia).", "**Methemoglobinemia and carbon monoxide** give falsely normal sats: use an **arterial blood gas** (co-oximetry).", "A warm sample left sitting gives false acidosis (WBCs use oxygen)."]}, {"t": 1080, "title": "Stridor by level", "notes": ["Above the glottis: **inspiratory** (epiglottitis). At or below the glottis: **biphasic** (croup, bacterial tracheitis). Intrathoracic: **expiratory** (wheeze, asthma)."]}, {"t": 1150, "title": "Epiglottitis vs croup vs bacterial tracheitis", "notes": ["**Epiglottitis**: supraglottic, 2 to 6 years, rapid onset, **toxic, drooling, tripod**, anxious, hoarseness rare. H influenzae (less with vaccine).", "**Croup**: subglottic, **6 to 36 months**, URI first, **barking cough**, hoarse, not toxic, often sudden at night. **Parainfluenza**.", "**Bacterial tracheitis**: 3 months to 6 years, rapid, **high fever, toxic**, no drooling. **S aureus**."]}, {"t": 1300, "title": "Retropharyngeal abscess", "notes": ["Under 6 years: high fever, **dysphagia, drooling, neck stiffness or hyperextension**, stridor, posterior pharyngeal bulge.", "Lateral neck x-ray: **prevertebral soft tissue wider than the vertebral body**. CT: hypodense collection with rim enhancement.", "Spreads to the mediastinum or epidural space. Rash with it: think Kawasaki or scarlet fever.", "Secure the airway, cultures, **ampicillin-sulbactam or clindamycin**, ENT to drain."]}, {"t": 1440, "title": "Peritonsillar abscess", "notes": ["**Adolescents**: severe sore throat, **trismus**, **hot potato voice**, **uvula deviated away**.", "Clinical diagnosis, no imaging needed. **Incision and drainage** gives fast relief."]}, {"t": 1535, "title": "Spasmodic croup", "notes": ["1 to 3 years, recurrent sudden **night-time** croup that resolves quickly. Linked to **reflux**, allergy, psychological factors."]}, {"t": 1570, "title": "Laryngomalacia", "notes": ["**Most common cause of inspiratory stridor in infants** (75% of chronic stridor).", "**Worse supine, crying or feeding, better prone**. Normal cry, normal growth: clinical diagnosis.", "Scope if severe, feeding trouble, poor growth. **Gets worse before better**, gone by 1 to 2 years. Surgery only if severe."]}, {"t": 1690, "title": "Vascular ring", "notes": ["Case: 2-week-old, **biphasic stridor that doesn't change with position or bronchodilator**, **right-sided aortic arch** on x-ray: vascular ring.", "Most common: **right aortic arch and double aortic arch** encircling trachea and esophagus. Screen for **22q11 deletion**.", "**Barium swallow** shows esophageal indentation. **CT or MRI** for anatomy. Treatment is surgery."]}, {"t": 1840, "title": "Vocal cord paralysis", "notes": ["**Second most common cause of infant stridor**. Unilateral: birth or **cardiac surgery** trauma, **weak cry**, better lying on the paralyzed side.", "Bilateral: high-pitched biphasic stridor, severe distress. Look for **Arnold-Chiari** or raised intracranial pressure: **head MRI**.", "Diagnosis: flexible laryngoscopy. Traumatic often recovers by 6 months. Bilateral may need tracheostomy."]}, {"t": 1945, "title": "Webs, hemangioma, papilloma, nodules", "notes": ["**Laryngeal web**: weak cry and biphasic stridor, surgery if significant.", "**Subglottic hemangioma**: half have **skin hemangiomas of the head and neck** (beard area). Stridor grows with the hemangioma. Treat with **propranolol**.", "**Laryngeal papillomas**: HPV 6 and 11 from the birth canal, **hoarseness**. Surgical removal.", "**Vocal nodules**: most common cause of chronic hoarseness (voice overuse, reflux). Voice rest."]}, {"t": 2050, "title": "Subglottic stenosis and tracheomalacia", "notes": ["Subglottic stenosis: mostly **acquired from prolonged intubation**. Biphasic stridor.", "**Tracheomalacia**: expiratory wheeze, **honking cough**, worse supine. Associated with **TE fistula and esophageal atresia**."]}, {"t": 2120, "title": "Cough: clues", "notes": ["Cough receptors from nose to lung (rhinitis, pharyngitis, sinusitis, even the ear canal).", "Staccato: **chlamydia** in infants. Whoop: pertussis. **Stops during sleep: habit or psychogenic cough**. Barking: croup, tracheomalacia.", "With eating: aspiration, reflux, **H-type TE fistula**. Throat clearing: postnasal drip. Night cough: sinusitis, asthma. Immunocompromised: PJP, TB, CMV."]}, {"t": 2275, "title": "Exposures and regional infections", "notes": ["Birds: psittacosis. Rodents: plague, **hantavirus**. Rabbits: tularemia. Sheep and cattle: **Q fever**.", "**Histoplasmosis**: Ohio and Mississippi valleys (bird and bat droppings). **Coccidioidomycosis**: US southwest. Blastomycosis: north and midwest."]}, {"t": 2340, "title": "Chronic cough workup", "notes": ["Purulent chronic sputum: bronchiectasis. Cough with anemia: **pulmonary hemosiderosis**. Nasal polyps, rectal prolapse, failure to thrive: **cystic fibrosis**.", "**Cough over 6 weeks without an explanation: sweat chloride test**. Over 3 weeks: chest x-ray, spirometry, CBC, urinalysis."]}, {"t": 2410, "title": "Clubbing and hemoptysis", "notes": ["Clubbing (hypertrophic pulmonary osteoarthropathy): **cyanotic heart disease** most common, **cystic fibrosis** most common lung cause, biliary cirrhosis, endocarditis, familial.", "Lost nail angle (Schamroth diamond gone).", "Coughed blood is bright red. **Check the nose first**."]}, {"t": 2525, "title": "Hemoptysis causes and workup", "notes": ["Foreign body, abscess, pneumonia, TB, CF, **idiopathic pulmonary hemosiderosis**, AVM, PE, pulmonary endometriosis (cyclic in girls).", "Vasculitis: lupus, **Goodpasture**, granulomatosis with polyangiitis (check urine and kidneys). Churg-Strauss: asthma, eosinophilia, nasal polyps.", "Check nose and throat first. **Acidic dark blood: stomach. Alkaline bright red: lung**."]}, {"t": 2610, "title": "Croup: presentation and severity", "notes": ["Laryngotracheobronchitis, **parainfluenza** most common. Subglottic narrowing, 3 months to 3 years.", "URI then **barking cough**, inspiratory or biphasic stridor, hoarse voice.", "**Clinical diagnosis**. Steeple sign may or may not be seen.", "Mild: occasional bark, no stridor at rest. Moderate: **stridor at rest**. Severe: persistent stridor, marked retractions, agitation."]}, {"t": 2740, "title": "Croup: management", "notes": ["**Dexamethasone 0.6 mg/kg** (oral, IM or IV, long half-life) for all severities, even mild.", "Moderate to severe: **nebulized epinephrine** (no rebound) plus oxygen. Heliox for severe.", "Discharge after epinephrine if no stridor at rest, good air entry, normal colour and alertness, dexamethasone given.", "Admit: persistent distress, hypoxia, can't drink, **2 or more epinephrine nebs**. Intubate early with a tube 0.5 to 1 mm smaller."]}, {"t": 2870, "title": "Bacterial tracheitis", "notes": ["**S aureus** (also Moraxella, strep), about 4 years. Looks like croup but **toxic, high fever, no response to epinephrine or steroids**.", "Can lie flat, no drooling (epiglottitis: sits forward, tripod, drools).", "Purulent secretions obstruct: **about 50% need intubation**. Antistaphylococcal antibiotics (nafcillin or vancomycin). Complications: toxic shock, ARDS."]}, {"t": 2990, "title": "Common cold and its mimics", "notes": ["**Green or thick discharge doesn't mean bacterial infection or sinusitis**. Cough medicines don't help young children.", "First-generation antihistamines reduce rhinorrhea, second-generation don't.", "Allergic rhinitis: itching, sneezing, nasal eosinophils. **Unilateral foul or bloody discharge: nasal foreign body**.", "Sinusitis: discharge **over 10 to 14 days**, or high fever with headache and facial pain. Strep nasal infection: crusting around the nostrils."]}, {"t": 3165, "title": "Bronchiolitis", "notes": ["Most common lower respiratory infection **under 2 years**. **RSV over 50%**. RSV-negative: **human metapneumovirus**, parainfluenza, adenovirus, rhinovirus.", "Risk for later asthma: maternal asthma or smoking, eczema under 1 year.", "URI, then **tachypnea (earliest, most sensitive sign)**, retractions, crackles and wheeze. **Apnea may be the only sign under 2 months or in ex-preemies**.", "**Worst on days 3 to 4**."]}, {"t": 3350, "title": "Bronchiolitis: diagnosis and management", "notes": ["**Clinical diagnosis**, no x-ray or blood work. X-ray if done: hyperinflation, peribronchial thickening, atelectasis.", "Admit based on **work of breathing and oxygen sats**. Supportive: oxygen, hydration, **nasal suction**.", "**No routine bronchodilators or steroids** (AAP). Trial salbutamol only with strong family asthma history. No ribavirin.", "Prevent: **palivizumab 15 mg/kg** for preterm and heart disease. RSV spreads by contact: **hand washing**."]}, {"t": 3510, "title": "Asthma severity classes", "notes": ["**Intermittent**: symptoms 2 days a week or less, nights 2 a month or less, normal lung function. **Salbutamol as needed only**.", "**Mild persistent**: over 2 days a week, over 2 nights a month, FEV1 over 80%. **Daily low-dose inhaled steroid**.", "**Moderate persistent**: daily symptoms, **nights over once a week**, FEV1 60 to 80%. Medium-dose inhaled steroid (or low dose plus LABA).", "**Severe persistent**: all day, most nights, FEV1 under 60%. Medium to high dose steroid plus LABA, consider oral steroid burst.", "Case: daily symptoms, worse with football, waking 3 to 4 nights a week: **moderate persistent**."]}, {"t": 3840, "title": "Asthma triggers and presentation", "notes": ["Risks: parental asthma, **eczema**, aeroallergen sensitization, food allergy, **eosinophils over 4%**.", "**Most common trigger: viral infection (rhinovirus)**. Also allergens, smoke, exercise, NSAIDs, beta blockers.", "Wheeze, but **no wheeze doesn't rule it out**: cough-only asthma, night or exercise cough, **chest tightness or pain**."]}, {"t": 3945, "title": "Severe asthma signs", "notes": ["Talking in words, agitated, tachypnea, retractions, **silent chest is worse, not better**.", "**Pulsus paradoxus over 20 mmHg**, sats under 91%.", "Impending failure: **normal or rising CO2**, bradycardia, drowsiness, confusion, paradoxical breathing."]}, {"t": 4075, "title": "Status asthmaticus and exacerbations", "notes": ["Oxygen, IV fluids, **continuous salbutamol plus ipratropium**, **early IV steroids** (work in 4 to 6 hours). **Magnesium sulfate** if not improving.", "Exacerbation at home: salbutamol for at least 5 days, **oral steroids 3 to 10 days**, early follow-up. **No antibiotics** (atelectasis is not pneumonia)."]}, {"t": 4235, "title": "Asthma diagnosis and exercise-induced asthma", "notes": ["Clinical diagnosis. Spirometry shows obstruction and response. **Exercise challenge** with spirometry before and after.", "Chest x-ray not needed (hyperinflation, atelectasis). Foreign body can mimic asthma. Skin or blood allergy testing.", "Exercise-induced: **warm up**, **salbutamol 15 minutes before exercise**. Needing more: add inhaled steroid or montelukast."]}, {"t": 4380, "title": "Asthma medicines", "notes": ["Needing lots of salbutamol means **poor control**. Salbutamol works in 15 minutes, lasts 3 to 4 hours.", "**LABA (salmeterol, formoterol) never alone**: risk of asthma death. Beta agonist side effects: tremor, tachycardia, **hypokalemia**.", "**Inhaled steroids are the main controller**. Slight first-year growth slowing, final height unchanged, **poorly controlled asthma slows growth more**. Rinse mouth (thrush), spacer.", "Montelukast: add-on, helps allergic rhinitis, viral wheeze, exercise asthma."]}, {"t": 4680, "title": "Asthma risk and inhaler devices", "notes": ["Future asthma risk under 3: **3 or more wheezing episodes a year**, eczema, parental asthma, allergic rhinitis, wheeze without colds, eosinophils over 4%.", "**MDI with spacer** is as good as a nebulizer and faster (**4 puffs = 2.5 mg nebulized**). Mask with spacer for young kids. Dry powder inhaler from about age 4."]}, {"t": 4875, "title": "Pneumonia: causes by clue", "notes": ["Case: 5-year-old, fever, cough, grunting, right crackles, **right middle lobe consolidation**.", "Infant afebrile staccato cough with interstitial infiltrates: **Chlamydia trachomatis**. **School age: Mycoplasma** (walking pneumonia). Pertussis: paroxysms, no fever.", "Histoplasmosis (Ohio and Mississippi valleys), coccidioidomycosis (California, Arizona), Legionella (water), tularemia (rabbits, ticks), psittacosis (parakeets), Q fever (farm animals). Varicella and measles cause pneumonia."]}, {"t": 4973, "title": "Pneumonia: signs", "notes": ["No fever or no cough doesn't rule it out. Can present as **chest or abdominal pain**. **Grunting** can signal impending failure.", "**Tachypnea is the most sensitive and specific sign**: over 50 at 2 to 12 months, over 40 at 1 to 5 years, over 20 after 5.", "Bacterial pneumonia unlikely with **no fever, no tachypnea, normal work of breathing and normal exam**."]}, {"t": 5055, "title": "Pneumonia: diagnosis and treatment", "notes": ["Clinical diagnosis. Outpatients usually need **no chest x-ray**. X-ray if complicated, prolonged fever, worsening, or febrile infant with no source. **X-ray lags clinical recovery**.", "Outpatient: **high-dose amoxicillin 80 to 90 mg/kg/day**. Over 5 years (Mycoplasma): **azithromycin**.", "Admit: sepsis, toxic, hypoxia, can't drink, failed outpatient treatment. Inpatient: ampicillin or **ceftriaxone**. Staph: vancomycin or clindamycin.", "Should improve in **48 to 96 hours**. If not: x-ray for empyema, TB, foreign body, CF, sequestration, aspiration."]}, {"t": 5250, "title": "Pleural effusion and empyema", "notes": ["Case: 15-month-old worsening on day 3 of pneumonia, decreased right breath sounds, **blunted costophrenic angle, shift to the left**: parapneumonic effusion or empyema.", "**Exudate** (Light): fluid to serum protein over 0.5, LDH ratio over 0.6, or LDH over 2/3 of upper normal. **Chylothorax is the most common newborn effusion**.", "Dullness, absent breath sounds, rub. **Ultrasound shows loculation**, CT for complicated cases. Thoracentesis, antibiotics, oxygen."]}, {"t": 5395, "title": "Tension pneumothorax and pneumothorax", "notes": ["Sudden collapse, absent breath sounds, **tracheal shift away**, sats 60%: **tension pneumothorax**. **Decompress immediately, no x-ray first**.", "Primary spontaneous: **tall thin males**, apical blebs, smoking. Secondary: lung disease, trauma, loud music.", "Under 5%: oxygen and observe. Over 5%, recurrent or tension: **chest tube**."]}, {"t": 5520, "title": "Aspiration and hydrocarbons", "notes": ["Gastric aspirate over 0.8 mL/kg or pH under 2.5: chemical pneumonitis. X-ray changes can take **1 to 2 days**.", "**Hydrocarbons** (gasoline, kerosene, lamp oil): can look well then crash. **Never empty the stomach or induce vomiting**.", "Suction the airway, don't neutralize. **No prophylactic antibiotics or steroids**, even with fever.", "**Asymptomatic with normal x-ray: observe 4 to 6 hours**. Abnormal x-ray: admit."]}, {"t": 5640, "title": "Foreign body aspiration", "notes": ["**Under 3 years**, nuts (peanuts a third), hot dogs, grapes.", "Choking episode, then a **symptom-free interval**, then chronic cough or **wheeze not responding to asthma treatment**. Exam can be normal.", "**A witnessed choking episode is never ignored**. Right main bronchus most often.", "Chest x-ray **normal in 10 to 30%** (radiolucent). Look for **unilateral air trapping** (inspiratory and expiratory or decubitus films). **Rigid bronchoscopy** if suspected, even with a normal x-ray."]}, {"t": 5880, "title": "Lung abscess", "notes": ["Cavity over 2 cm from aspiration or infection. Risk: dysphagia, developmental delay, poor airway protection, neuromuscular weakness.", "Fever, cough, sputum, hemoptysis, weight loss. **Air-fluid level** on x-ray.", "**Clindamycin** (anaerobes): IV 2 to 3 weeks, then oral to 4 to 6 weeks."]}, {"t": 5950, "title": "Pulmonary sequestration", "notes": ["Non-functioning lung with **systemic arterial supply**, no airway connection.", "**Extralobar**: more common, own pleura, presents in infancy, with **congenital diaphragmatic hernia**. **Intralobar**: inside normal pleura, **recurrent pneumonia** in older kids. Both usually left lower.", "CT with contrast. **Surgical removal**."]}, {"t": 6120, "title": "Bronchogenic cyst, lobar emphysema, CPAM", "notes": ["**Bronchogenic cyst**: **sharply demarcated spherical mass in the middle mediastinum near the carina**. Dysphagia, cough, recurrent pneumonia. Remove surgically.", "Congenital lobar emphysema: air in, not out, **one lobe overinflates**, newborn distress.", "**CPAM (cystic adenomatoid malformation)**: air-filled cysts, newborn distress or later recurrent infections. Surgical removal."]}, {"t": 6330, "title": "Primary ciliary dyskinesia and bronchiectasis", "notes": ["**PCD**: autosomal recessive, impaired mucociliary clearance, **situs inversus** (Kartagener) in some, **male infertility**. Chronic wet cough, sinusitis, **otitis media**, bronchiectasis. Electron microscopy of cilia.", "**Bronchiectasis**: most common cause **cystic fibrosis**. Chronic productive cough, crackles, clubbing. **CT is best**."]}, {"t": 6450, "title": "Bronchopulmonary dysplasia", "notes": ["Chronic lung disease of extreme preemies from ventilation, oxygen, barotrauma.", "Tachypnea, increased work, **frequent desaturations**. X-ray: low volumes, atelectasis, hyperinflation, interstitial emphysema.", "Surfactant, gentle ventilation, **permissive hypercapnia**, avoid too much oxygen (ROP), diuretics, treat PDA, watch for pulmonary hypertension and reflux."]}, {"t": 6520, "title": "Pulmonary hemosiderosis", "notes": ["Repeated alveolar bleeding with hemosiderin-laden macrophages: **lung symptoms plus severe iron deficiency anemia**.", "Idiopathic most common. Also heart failure, Goodpasture, granulomatosis with polyangiitis, HSP, **cow's milk (Heiner syndrome)**.", "Hemoptysis, wheeze, microcytic anemia, bilateral infiltrates. **Steroids** for idiopathic."]}, {"t": 6655, "title": "Sarcoidosis", "notes": ["Non-caseating granulomas, more common in Black patients. **Bilateral hilar lymphadenopathy**, can be incidental.", "Fever, cough, erythema nodosum. **Hypercalcemia, hypercalciuria, high ACE level**. Steroids for symptomatic cases."]}, {"t": 6735, "title": "Cystic fibrosis: lungs and newborn", "notes": ["Autosomal recessive **CFTR, chromosome 7, F508del** most common.", "Chronic cough (**test if over 6 weeks**), barrel chest, crackles, clubbing, **nasal polyps (red flag)**. Pathogens: **S aureus early, Pseudomonas later**.", "**Meconium ileus** in 15 to 20%: distension, vomiting, no meconium, ground-glass bubbly bowel. **Gastrografin enema** diagnostic and therapeutic."]}, {"t": 6835, "title": "Cystic fibrosis: GI and other", "notes": ["Pancreatic insufficiency: failure to thrive, **bulky greasy foul stools**, **A, D, E, K deficiency** (night blindness, low bone density, neuropathy and hemolysis, bleeding).", "Delayed puberty, **azoospermia**, **distal intestinal obstruction syndrome** in teens (missed enzymes), **rectal prolapse**, biliary cirrhosis, **CF-related diabetes**."]}, {"t": 6940, "title": "Cystic fibrosis: diagnosis and treatment", "notes": ["Newborn screen first. **Sweat chloride is the gold standard**: **over 60** diagnostic (**over 40 under 6 months**). Repeat to confirm.", "False positives: eczema, adrenal insufficiency, ectodermal dysplasia, nephrogenic DI, G6PD, hypothyroidism, malnutrition.", "Pancreatic tests: fecal elastase, **72-hour fecal fat**. Treatment: enzymes, vitamins, bronchodilators, hypertonic saline, **dornase**, antibiotics. Survival now past 50."]}, {"t": 7090, "title": "Obstructive sleep apnea", "notes": ["Primary snoring: no apneas or gas exchange problems. OSA: **apneas, poor sleep, CO2 retention**, can lead to **pulmonary hypertension and right heart failure**.", "Risks: **big tonsils and adenoids**, obesity, midface hypoplasia, **Down syndrome**, neuromuscular disease, cerebral palsy.", "Snoring with witnessed pauses, mouth breathing, morning headache, sleepiness. Can look like **ADHD** and cause **enuresis**.", "**Polysomnography** is diagnostic. **Adenotonsillectomy first line**, CPAP otherwise. Post-op risk: pulmonary edema."]}, {"t": 7270, "title": "Apnea and BRUE", "notes": ["Central apnea: idiopathic most common, prematurity, infection, reflux, seizures, arrhythmia, **abuse**.", "Awake events: **reflux most common**, then seizures. **RSV can present with apnea before bronchiolitis**."]}, {"t": 7340, "title": "SIDS prevention", "notes": ["**Back to sleep** under 1 year, tummy time only while awake and watched, **no smoking**.", "Risks: prematurity, low birth weight, **co-sleeping**, prone sleep, overheating, young mother, poor prenatal care.", "**Pacifier at sleep lowers SIDS risk** (once breastfeeding is established). **Apnea monitors don't reduce SIDS**."]}, {"t": 7415, "title": "Pectus excavatum and carinatum", "notes": ["Excavatum: with **Marfan, Ehlers-Danlos**. Usually asymptomatic, surgery only if physiologic compromise.", "Carinatum: sternum pushed out, mostly cosmetic, reassure."]}], "tx": true}, {"key": "n_T_iOTXPYp9s", "id": "T_iOTXPYp9s", "who": "Dr Osama Naga", "title": "Asthma Management (new GINA guideline)", "len": 2254, "approx": false, "sys": "pulm", "sections": [{"t": 0, "title": "Case and asthma phenotypes", "notes": ["6-year-old with eczema, allergic rhinitis, cough early morning and with play, clear lungs: **asthma**.", "Transient early wheeze (under 1 year, outgrown), non-atopic early onset, late onset (over 3 years), persistent early onset (mostly atopic).", "More common in boys before puberty, **more severe in girls after**."]}, {"t": 95, "title": "Asthma predictive index", "notes": ["Predicts persistent asthma. **One major**: parental asthma, **eczema**, aeroallergen sensitization.", "**Or two minor**: food sensitization, **eosinophils over 4%**, wheezing without colds."]}, {"t": 160, "title": "Pathophysiology", "notes": ["Allergen, **IgE**, mast cells: edema, vasodilation, mucus, **bronchoconstriction**.", "Plus inflammation (IL-4, IL-5, IL-13, eosinophils). Treat both: **bronchodilator plus anti-inflammatory (inhaled steroid)**."]}, {"t": 260, "title": "Triggers and symptoms", "notes": ["**Viral infection is the most common trigger (rhinovirus)**. RSV or rhinovirus bronchiolitis raises later asthma risk.", "Smoke (even outside), pollution, **NSAIDs, beta blockers**, exercise, pollen, pets, dust mites, cockroaches, mould, weather.", "Wheeze, chest tightness (young kids call it chest pain), dyspnea, cough, **worse at night and early morning**. Forced exhalation brings out wheeze."]}, {"t": 385, "title": "Diagnosis", "notes": ["Spirometry over 5 years: **low FEV1 with normal FVC**, scooped flow-volume loop. Exercise challenge for exercise-induced asthma.", "Allergy testing for persistent asthma (pets, environment).", "**Chest x-ray not needed**: hyperinflation, peribronchial thickening, **atelectasis often mistaken for pneumonia**."]}, {"t": 560, "title": "Exercise-induced asthma", "notes": ["15-minute **warm-up**, scarf or mask helps 80%.", "**Salbutamol before exercise** protects 2 to 3 hours. Montelukast helps about 50% but takes hours."]}, {"t": 615, "title": "Follow-up and inhaler technique", "notes": ["Reassess every 2 to 6 weeks at first, then every 1 to 6 months. Spirometry at start, 3 to 6 months later, then every 1 to 2 years.", "**Inhaler technique is the most important step**: watch them use it.", "**MDI with spacer works at any age**. Mask under about 3 years, mouthpiece over 5. **Dry powder inhalers not for under 5**."]}, {"t": 840, "title": "Beta agonists and inhaled steroids", "notes": ["SABA (salbutamol): works in 15 minutes, lasts 3 to 4 hours. LABA (salmeterol, formoterol): 12 hours, **only with an inhaled steroid**.", "New guideline: **add a LABA rather than doubling the inhaled steroid**.", "Beta agonist side effects: tremor, tachycardia, **hypokalemia**, masked hypoglycemia in diabetes.", "**Inhaled steroids are the best long-term controller** and improve lung function. Growth slows slightly but final height is reached. Rinse mouth (thrush). Osteoporosis with high doses."]}, {"t": 1010, "title": "ICS-formoterol: MART and AIR", "notes": ["**Only formoterol** (fast onset) can be the reliever in combination. Salmeterol can't.", "**MART**: one ICS-formoterol inhaler as daily maintenance and as reliever. **AIR**: ICS-formoterol as needed only (anti-inflammatory reliever).", "Max: 8 puffs a day ages 6 to 11, 12 puffs over 12."]}, {"t": 1170, "title": "Montelukast and LAMA", "notes": ["Montelukast blocks leukotriene D4 receptor. Add-on, helps allergic rhinitis, viral wheeze, **exercise asthma**. **Black box: mood changes, aggression, suicidal thoughts**.", "**LAMA (tiotropium)**: add-on to ICS-LABA for moderate to severe, over 6 years. Side effects: dry mouth."]}, {"t": 1295, "title": "Exacerbation severity", "notes": ["Mild to moderate: talks in phrases, not agitated, **sats over 90%, peak flow over 50%**.", "Severe: **talks in words**, hunched, agitated, accessory muscles, pulsus paradoxus over 20, **sats under 90%, peak flow under 50%**.", "Life-threatening: **silent chest**, drowsy, confused, exhausted."]}, {"t": 1380, "title": "Home and office management of exacerbations", "notes": ["Written **asthma action plan**. AIR or more salbutamol. In 6 to 11 year olds, **doubling the inhaled steroid alone doesn't help**.", "Oral steroids 3 to 5 days if no response to reliever in 2 to 3 days or peak flow under 60%.", "Office: **salbutamol 4 to 10 puffs with spacer every 20 minutes x 3**, **prednisone 1 to 2 mg/kg (max 40)**, oxygen to sats 94 to 98%. Reassess at 1 hour, discharge if well, follow up in 1 to 2 days.", "Severe or worsening: transfer to ED, add **ipratropium**."]}, {"t": 1550, "title": "Stepwise therapy (GINA 2023)", "notes": ["Ages 6 to 11: symptoms under twice a month: SABA plus low-dose ICS. Twice a month or more: **daily low-dose ICS**.", "Most days or waking once a week: low or medium ICS, low ICS-LABA, or very low ICS-formoterol MART.", "Daily or with low lung function: medium ICS-LABA or low ICS-formoterol MART, refer. Uncontrolled: specialist, biologics.", "12 and over: **as-needed low-dose ICS-formoterol (AIR)** at step 1 to 2, then ICS-formoterol MART at increasing doses, then add LAMA."]}, {"t": 1790, "title": "Case: still coughing on fluticasone", "notes": ["6-year-old using fluticasone correctly plus montelukast, still coughing: **switch to ICS-formoterol daily and as needed**, don't just raise the fluticasone dose."]}, {"t": 1840, "title": "Asthma under 5 years", "notes": ["Rule out other causes (congenital lung disease). Likely asthma: over 10 days of cough, wheeze with **more than 3 URIs a year**, night symptoms, **symptoms between colds**, atopy.", "Step 1: SABA plus **low-dose ICS at the start of each viral illness**. Step 2: daily low-dose ICS for 3 months. Step 3: check diagnosis and technique, double ICS, refer."]}, {"t": 1950, "title": "Risk of asthma death", "notes": ["**More than 1 salbutamol canister a month**, non-Hispanic Black, **previous intubation** (single strongest predictor), hospital or ED visit in the past year, recent oral steroids."]}, {"t": 2010, "title": "Severe exacerbation and impending failure", "notes": ["Case: 7-year-old talking in words, sats 88%, retractions: **send to the ED**.", "Paradoxical breathing, **silent chest, bradycardia**, pulsus paradoxus disappears (fatigue), confusion. **Normal or rising CO2** is a bad sign.", "Status asthmaticus: admit, fluids, oxygen, **continuous salbutamol**, ipratropium, IV steroids, **magnesium sulfate**."]}], "tx": true}, {"key": "n_PRz4BjBXvV8", "id": "PRz4BjBXvV8", "who": "Dr Osama Naga", "title": "Pediatric Neurology", "len": 6339, "approx": false, "sys": "neuro", "sections": [], "tx": true}, {"key": "n_chSzASUZHko", "id": "chSzASUZHko", "who": "Dr Osama Naga", "title": "Pediatric Hematology Board Review", "len": 8210, "approx": false, "sys": "heme", "sections": [], "tx": true}, {"key": "n_Q4kheuaX8ao", "id": "Q4kheuaX8ao", "who": "Dr Osama Naga", "title": "Leukemia and Lymphoma", "len": 2034, "approx": false, "sys": "heme", "sections": [], "tx": true}, {"key": "n_ddI6c-XT4Bg", "id": "ddI6c-XT4Bg", "who": "Dr Osama Naga", "title": "Brain Tumors and Solid Masses", "len": 1902, "approx": false, "sys": "heme", "sections": [], "tx": false}, {"key": "n_ScZTwgZgQlc", "id": "ScZTwgZgQlc", "who": "Dr Osama Naga", "title": "ADHD", "len": 1297, "approx": false, "sys": "psych", "sections": [], "tx": false}, {"key": "n_GTYXOmODHHc", "id": "GTYXOmODHHc", "who": "Dr Osama Naga", "title": "Autism Spectrum Disorder", "len": 932, "approx": false, "sys": "psych", "sections": [], "tx": true}, {"key": "n_Zh-NMjWB-i0", "id": "Zh-NMjWB-i0", "who": "Dr Osama Naga", "title": "Pediatric Emergency Medicine", "len": 2701, "approx": false, "sys": "tox", "sections": [], "tx": true}, {"key": "n_0Mv9aA9F3xM", "id": "0Mv9aA9F3xM", "who": "Dr Osama Naga", "title": "Foreign Body Ingestions (updated guidelines)", "len": 419, "approx": false, "sys": "tox", "sections": [], "tx": true}, {"key": "n_otmJ72_ctz0", "id": "otmJ72_ctz0", "who": "Dr Osama Naga", "title": "Immunologic Disorders", "len": 2902, "approx": false, "sys": "immuno", "sections": [], "tx": true}, {"key": "n_YORjYrfzQ10", "id": "YORjYrfzQ10", "who": "Dr Osama Naga", "title": "Labial Adhesion", "len": 236, "approx": false, "sys": "frepro", "sections": [], "tx": true}, {"key": "n_uJH4s2ZmPaU", "id": "uJH4s2ZmPaU", "who": "Dr Osama Naga", "title": "Genetic Disorders I", "len": 1377, "approx": false, "sys": "multi", "sections": [], "tx": true}, {"key": "n_w5IhrBLM_LI", "id": "w5IhrBLM_LI", "who": "Dr Osama Naga", "title": "Genetic Disorders II", "len": 928, "approx": false, "sys": "multi", "sections": [], "tx": false}, {"key": "n_m1o_HfViIBY", "id": "m1o_HfViIBY", "who": "Dr Osama Naga", "title": "Genetic Disorders III", "len": 2445, "approx": false, "sys": "multi", "sections": [], "tx": false}, {"key": "n_mpW672XvTDI", "id": "mpW672XvTDI", "who": "Dr Osama Naga", "title": "Hearing Loss and Audiograms", "len": 903, "approx": false, "sys": "ent", "sections": [], "tx": true}, {"key": "n_0nDGidKiAmc", "id": "0nDGidKiAmc", "who": "Dr Osama Naga", "title": "Otitis Media", "len": 579, "approx": false, "sys": "ent", "sections": [], "tx": true}, {"key": "n_MCajj6eQ6oo", "id": "MCajj6eQ6oo", "who": "Dr Osama Naga", "title": "Antibiotics (ID I)", "len": 2482, "approx": false, "sys": "id", "sections": [], "tx": true}, {"key": "n_a-CCxW4WhUw", "id": "a-CCxW4WhUw", "who": "Dr Osama Naga", "title": "Staph aureus (ID II)", "len": 1207, "approx": false, "sys": "id", "sections": [], "tx": true}, {"key": "n_yoTIeRNV86k", "id": "yoTIeRNV86k", "who": "Dr Osama Naga", "title": "Streptococcal Infections (ID III)", "len": 911, "approx": false, "sys": "id", "sections": [], "tx": true}, {"key": "n_2W1mV2F9wVY", "id": "2W1mV2F9wVY", "who": "Dr Osama Naga", "title": "Viral Infections (ID IV)", "len": 1877, "approx": false, "sys": "id", "sections": [], "tx": true}, {"key": "n_MB-tYihLi3A", "id": "MB-tYihLi3A", "who": "Dr Osama Naga", "title": "Neonatal Sepsis and Jaundice", "len": 1595, "approx": false, "sys": "newborn", "sections": [], "tx": true}, {"key": "n_5t1zOzVWu54", "id": "5t1zOzVWu54", "who": "Dr Osama Naga", "title": "Newborn Examination", "len": 2875, "approx": false, "sys": "newborn", "sections": [], "tx": true}, {"key": "n_dPdv10lm1OI", "id": "dPdv10lm1OI", "who": "Dr Osama Naga", "title": "Pediatric Dermatology", "len": 3848, "approx": false, "sys": "derm", "sections": [], "tx": true}, {"key": "n_M6BvRbh3S5Y", "id": "M6BvRbh3S5Y", "who": "Dr Osama Naga", "title": "Pediatric Rheumatology", "len": 1991, "approx": false, "sys": "msk", "sections": [], "tx": true}, {"key": "n_xWwLFbvLLaY", "id": "xWwLFbvLLaY", "who": "Dr Osama Naga", "title": "The Limping Child", "len": 1968, "approx": false, "sys": "msk", "sections": [], "tx": true}, {"key": "n_IrTqUqu_OcY", "id": "IrTqUqu_OcY", "who": "Dr Osama Naga", "title": "General Pediatrics Board Review", "len": 5325, "approx": false, "sys": "gen", "sections": [], "tx": true}, {"key": "n_obkrsMyFsdU", "id": "obkrsMyFsdU", "who": "Dr Osama Naga", "title": "Developmental Milestones 2026", "len": 555, "approx": false, "sys": "gen", "sections": [], "tx": false}, {"key": "n_8wv-cXAFZ6U", "id": "8wv-cXAFZ6U", "who": "Dr Osama Naga", "title": "Research and Statistics", "len": 1101, "approx": false, "sys": "gen", "sections": [], "tx": true}];
